// Ahorro.js
import React, { useState, useEffect } from 'react';
import './Ahorro.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const Ahorro = ({ userId }) => {
    const [salary, setSalary] = useState(null);
    const [monthlyExpenses, setMonthlyExpenses] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (!userId) return;

        const fetchData = async () => {
            setLoading(true);
            setError(null);
            try {
                // Suponiendo que la API para obtener el formulario inicial es /api/forms/initial/getInitial/:userId
                const response = await fetch(`${API_URL}/api/forms/initial/getInitial/${userId}`);
                if (!response.ok) {
                    throw new Error('Error al obtener los datos de ahorro');
                }
                const data = await response.json();
                setSalary(data.salary);
                setMonthlyExpenses(data.monthlyExpenses);
            } catch (err) {
                console.error(err);
                setError('Hubo un error al cargar los datos de ahorro. Por favor, intenta nuevamente.');
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [userId]);

    const calculateSavings = () => {
        const salario = parseFloat(salary);
        const gastos = parseFloat(monthlyExpenses);
        if (isNaN(salario) || isNaN(gastos)) {
            return 'Datos incompletos';
        }
        const ahorro = salario - gastos;
        return ahorro.toFixed(2);
    };

    const formatCurrency = (number) => {
        if (isNaN(number)) return 'No disponible';
        return new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(number);
    };

    const savings = calculateSavings();

    if (loading) {
        return <div className="loading">Cargando datos de ahorro...</div>;
    }

    if (error) {
        return <div className="error-message">{error}</div>;
    }

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <table>
                    <tbody>
                        <tr>
                            <th>Salario Mensual:</th>
                            <td>{salary !== null ? formatCurrency(salary) : 'No disponible'}</td>
                        </tr>
                        <tr>
                            <th>Gastos Mensuales:</th>
                            <td>{monthlyExpenses !== null ? formatCurrency(monthlyExpenses) : 'No disponible'}</td>
                        </tr>
                        <tr>
                            <th>Ahorro Mensual:</th>
                            <td>
                                {typeof savings === 'string' ? (
                                    savings
                                ) : (
                                    <span className={savings >= 0 ? 'positive' : 'negative'}>
                                        {formatCurrency(savings)}
                                    </span>
                                )}
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Ahorro;
